import{_ as n,a0 as r,w as p,s as o,I as t,x as a,a1 as e,A as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"Kali Linux 是什么，你需要它吗？ | LCTT x X-CMD","titleTemplate":false,"description":"Kali Linux 是什么，你需要它吗？ | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kali Linux 是什么，你需要它吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kali Linux 是什么，你需要它吗？ | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180206 What Is Kali Linux, and Do You Need It","title":"Kali Linux 是什么，你需要它吗？","tag":"201802","desc":""},"relativePath":"201802/20180206 What Is Kali Linux, and Do You Need It.md","filePath":"[post].md"}'),d={name:"201802/20180206 What Is Kali Linux, and Do You Need It.md"};function m(x,i,K,w,k,f){const l=r("Link");return p(),o("div",null,[i[20]||(i[20]=t("h1",{id:"kali-linux-是什么-你需要它吗",tabindex:"-1"},[a("Kali Linux 是什么，你需要它吗？ "),t("a",{class:"header-anchor",href:"#kali-linux-是什么-你需要它吗","aria-label":"Permalink to “Kali Linux 是什么，你需要它吗？”"},"​")],-1)),i[21]||(i[21]=t("p",null,[t("img",{src:"https://www.maketecheasier.com/assets/uploads/2018/01/kl-feat.jpg",alt:""})],-1)),i[22]||(i[22]=t("p",null,"如果你听到一个 13 岁的黑客吹嘘他是多么的牛逼，是有可能的，因为有 Kali Linux 的存在。尽管有可能会被称为“脚本小子”，但是事实上，Kali 仍旧是安全专家手头的重要工具（或工具集）。",-1)),i[23]||(i[23]=t("p",null,"Kali 是一个基于 Debian 的 Linux 发行版。它的目标就是为了简单：在一个实用的工具包里尽可能多的包含渗透和审计工具。Kali 实现了这个目标。大多数做安全测试的开源工具都被囊括在内。",-1)),t("p",null,[i[1]||(i[1]=t("strong",null,"相关",-1)),i[2]||(i[2]=a(" ： ",-1)),e(l,{href:"https://www.maketecheasier.com/linux-distros-designed-for-privacy-security/",title:"4 Great Linux Distros Designed for Privacy and Security"},{default:s(()=>[...i[0]||(i[0]=[a("4 个极好的为隐私和安全设计的 Linux 发行版",-1)])]),_:1})]),i[24]||(i[24]=t("h3",{id:"为什么是-kali",tabindex:"-1"},[a("为什么是 Kali？ "),t("a",{class:"header-anchor",href:"#为什么是-kali","aria-label":"Permalink to “为什么是 Kali？”"},"​")],-1)),i[25]||(i[25]=t("p",null,[t("img",{src:"https://www.maketecheasier.com/assets/uploads/2018/01/kl-desktop.jpg",alt:"Kali Linux Desktop",title:"Kali Linux Desktop"})],-1)),t("p",null,[e(l,{href:"https://www.offensive-security.com/kali-linux-vmware-virtualbox-image-download/"},{default:s(()=>[...i[3]||(i[3]=[a("Kali",-1)])]),_:1}),i[5]||(i[5]=a(" 是由 ",-1)),e(l,{href:"https://www.offensive-security.com/"},{default:s(()=>[...i[4]||(i[4]=[a("Offensive Security",-1)])]),_:1}),i[6]||(i[6]=a(" 公司开发和维护的。它在安全领域是一家知名的、值得信赖的公司，它甚至还有一些受人尊敬的认证，来对安全从业人员做资格认证。",-1))]),i[26]||(i[26]=u('<p>Kali 也是一个简便的安全解决方案。Kali 并不要求你自己去维护一个 Linux 系统，或者你自己去收集软件和依赖项。它是一个“交钥匙工程”。所有这些繁杂的工作都不需要你去考虑，因此，你只需要专注于要审计的真实工作上，而不需要去考虑准备测试系统。</p><h3 id="如何使用它" tabindex="-1">如何使用它？ <a class="header-anchor" href="#如何使用它" aria-label="Permalink to “如何使用它？”">​</a></h3><p>Kali 是一个 Linux 发行版。与任何一个其它的 Linux 发行版一样，你可以将它永久安装到一个硬盘上。那样它会工作的更好，但是你不能将它作为一个日常使用的操作系统。因为它是为渗透测试构建的，这就是你使用它的全部理由。</p><p>最好是将 Kali 制作为自启动发行版。你可以将 Kali 刻录到一张 DVD 或者是制作到一个自启动 U 盘上来运行它。你没有必要在一个 Kali 上安装任何软件或者保存任何文件。你可以在需要测试一个系统时随时来启动它。它也有非常好的灵活性，可以让运行 Kali 的机器随时运行在想要测试的网络上。</p><h3 id="kali-可以做什么" tabindex="-1">Kali 可以做什么？ <a class="header-anchor" href="#kali-可以做什么" aria-label="Permalink to “Kali 可以做什么？”">​</a></h3><p>Kali 里面有很多的安全工具而不是别的。这就是它能做的事。不管怎么说，Kali 就是一个安全工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-zenmap.jpg" alt="Kali Zenmap" title="Kali Zenmap"></p><p>它有像 NMap 和 Wireskark 这样的经典信息采集工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-wireshark.jpg" alt="Kali Linux Wireshark" title="Kali Linux Wireshark"></p><p>Kali 也有面向 WiFi 的工具，像 Aircrack-ng、Kismet、以及 Pixie。</p><p>对于破解密码，它也有像 Hydra、Crunch、Hashcat、以及 John the Ripper 这样的工具。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2018/01/kl-metasploit.jpg" alt="Kali Metasploit" title="Kali Metasploit"></p><p>还有更多的成套工具，包括 Metasploit 和 Burp Suite。</p><p>这些只是 Kali 缺省内置的一小部分安全工具。完整的了解这些工具需要很多的时间，但是，你可以清楚地看到许多非常流行的工具它都有。</p><h3 id="kali-是为你准备的吗" tabindex="-1">Kali 是为你准备的吗？ <a class="header-anchor" href="#kali-是为你准备的吗" aria-label="Permalink to “Kali 是为你准备的吗？”">​</a></h3><p>Kali 并不是为普通用户准备的。它并不是一个运行在你的笔记本电脑上的普通 Linux 发行版，而是一个很酷的“黑客操作系统“。如果你使用这个操作系统，那么你将会运行着一个缺乏安全保障的系统，因为 Kali 被设计为以 root 权限运行。它自身并不安全，并且它的配置也与普通的 Linux 发行版不一样。它是一个攻击型工具，而不是一个防御型工具。</p><p>Kali 并不是个玩具。你可以使用它内置的工具去做一些会产生真实伤害的危险的事（你懂的），那将给你带来很多真实的麻烦。对于一个未受到严格教育的用户来说，做一些严重违法的事情是很容易的，并且之后你就会发现自己被陷入很无助的境地。</p><p>说了这么多，但是，Kali 对于一个专业用户来说，它是一个极好的工具。如果你是一个网络管理员，想对你的网络做一个真实的测试，Kali 可以做到你所希望的一切事情。Kali 也有一些优秀的开发工具，用于去实时审计它们的应用程序。</p><p>当然，如果你正好有兴趣学习关于安全的知识，你可以在某些受控环境中去使用 Kali，它可以教你学习很多的非常优秀的知识。</p><p>Kali Linux 是许多优秀的安全工具的集合。对于专业用户来说，它有难以置信的好处，但是对于一些不怀好意的人来说，也可以产生很多大麻烦。小心地使用 Kali，充分利用它的巨大优势。如果不这样的话，你将在某个地方（你懂的）度过你的余生。</p><hr>',21)),t("p",null,[i[8]||(i[8]=a("via: ",-1)),e(l,{href:"https://www.maketecheasier.com/what-is-kali-linux-and-do-you-need-it/"},{default:s(()=>[...i[7]||(i[7]=[a("https://www.maketecheasier.com/what-is-kali-linux-and-do-you-need-it/",-1)])]),_:1})]),t("p",null,[i[12]||(i[12]=a("作者：",-1)),e(l,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:s(()=>[...i[9]||(i[9]=[a("Nick Congleton",-1)])]),_:1}),i[13]||(i[13]=a(" 译者：",-1)),e(l,{href:"https://github.com/qhwdw"},{default:s(()=>[...i[10]||(i[10]=[a("qhwdw",-1)])]),_:1}),i[14]||(i[14]=a(" 校对：",-1)),e(l,{href:"https://github.com/wxy"},{default:s(()=>[...i[11]||(i[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[i[17]||(i[17]=a("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[15]||(i[15]=[a("LCTT",-1)])]),_:1}),i[18]||(i[18]=a(" 原创编译，",-1)),e(l,{href:"https://linux.cn/"},{default:s(()=>[...i[16]||(i[16]=[a("Linux中国",-1)])]),_:1}),i[19]||(i[19]=a(" 荣誉推出",-1))])])}const T=n(d,[["render",m]]);export{g as __pageData,T as default};
